const base = { name: '셔츠', price: 39000 };
const patch = { price: 9900 };

const merged = { ...base, ...patch };

function getMerged() {
  return merged;
}

function toCard(product, overrides) {
  const { id, name = '이름 없음', price } = product;

  return { id, name, price, ...overrides };
}
